head.b:skin:
/* ---------- Design tokens ---------- */
:root{
  --bg:#0b1020;
  --bg-2:#111833;
  --surface:#ffffff;
  --surface-2:#f5f7fb;
  --text:#0f172a;
  --muted:#5b6478;
  --line:#e3e8f2;
  --accent:#4f46e5;
  --accent-2:#06b6d4;
  --radius:18px;
  --shadow:0 10px 30px rgba(15,23,42,.08);
  --max:1160px;
}
*{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:'Inter',system-ui,-apple-system,Segoe UI,Roboto,sans-serif;color:var(--text);background:var(--surface);line-height:1.6;-webkit-font-smoothing:antialiased}
a{color:inherit;text-decoration:none}
img{max-width:100%;display:block}
.container{width:100%;max-width:var(--max);margin:0 auto;padding:0 20px}
.section{padding:96px 0}
.eyebrow{display:inline-block;font-size:13px;font-weight:600;letter-spacing:.12em;text-transform:uppercase;color:var(--accent);margin-bottom:12px}
.section-title{font-size:clamp(28px,4vw,40px);line-height:1.15;font-weight:800;letter-spacing:-.02em;margin-bottom:16px}
.section-lead{color:var(--muted);font-size:18px;max-width:640px}
.center{text-align:center}
.center .section-lead{margin:0 auto}

/* ---------- Buttons ---------- */
.btn{display:inline-flex;align-items:center;gap:10px;padding:14px 26px;border-radius:999px;font-weight:600;font-size:15px;transition:transform .2s,box-shadow .2s,background .2s}
.btn:hover{transform:translateY(-2px)}
.btn-primary{background:linear-gradient(135deg,var(--accent),var(--accent-2));color:#fff;box-shadow:0 10px 25px rgba(79,70,229,.35)}
.btn-ghost{border:1px solid rgba(255,255,255,.25);color:#fff}
.btn-ghost:hover{background:rgba(255,255,255,.08)}
.btn-dark{background:var(--text);color:#fff}

/* ---------- Header ---------- */
.site-header{position:fixed;top:0;left:0;right:0;z-index:50;transition:background .3s,box-shadow .3s}
.site-header.scrolled,.is-page .site-header{background:rgba(11,16,32,.92);backdrop-filter:blur(12px);box-shadow:0 1px 0 rgba(255,255,255,.06)}
.nav{display:flex;align-items:center;justify-content:space-between;height:72px}
.brand{display:flex;align-items:center;gap:10px;color:#fff;font-weight:800;font-size:19px;letter-spacing:-.01em}
.brand-mark{width:36px;height:36px;border-radius:10px;background:linear-gradient(135deg,var(--accent),var(--accent-2));display:grid;place-items:center;font-size:16px;color:#fff}
.nav-links{display:flex;gap:32px;list-style:none}
.nav-links a{color:rgba(255,255,255,.8);font-size:15px;font-weight:500}
.nav-links a:hover{color:#fff}
.nav-cta{padding:10px 20px;font-size:14px}
.menu-btn{display:none;background:none;border:0;color:#fff;cursor:pointer;padding:8px}
.menu-btn span{display:block;width:22px;height:2px;background:#fff;margin:5px 0;border-radius:2px}

/* ---------- Hero ---------- */
.hero{position:relative;background:radial-gradient(1200px 600px at 80% -10%,rgba(6,182,212,.25),transparent 60%),radial-gradient(900px 500px at 0% 10%,rgba(79,70,229,.35),transparent 60%),var(--bg);color:#fff;padding:180px 0 120px;overflow:hidden}
.hero-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:56px;align-items:center}
.badge{display:inline-flex;align-items:center;gap:8px;padding:6px 14px;border-radius:999px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.12);font-size:13px;color:rgba(255,255,255,.85);margin-bottom:24px}
.badge i{width:8px;height:8px;border-radius:50%;background:#22c55e;box-shadow:0 0 0 4px rgba(34,197,94,.2)}
.hero h1{font-size:clamp(38px,6vw,64px);line-height:1.05;font-weight:800;letter-spacing:-.03em;margin-bottom:22px}
.hero h1 .grad{background:linear-gradient(135deg,#a5b4fc,#67e8f9);-webkit-background-clip:text;background-clip:text;color:transparent}
.hero p{font-size:19px;color:rgba(255,255,255,.72);max-width:560px;margin-bottom:36px}
.hero-actions{display:flex;flex-wrap:wrap;gap:14px}
.phone{position:relative;margin:0 auto;width:270px;height:540px;border-radius:44px;background:linear-gradient(160deg,#1e2747,#0d1328);border:1px solid rgba(255,255,255,.12);box-shadow:0 40px 80px rgba(0,0,0,.45);padding:14px}
.phone-screen{height:100%;border-radius:32px;background:linear-gradient(180deg,#151d3b,#0b1020);padding:26px 18px;display:flex;flex-direction:column;gap:14px;overflow:hidden}
.phone-row{display:flex;align-items:center;gap:12px;background:rgba(255,255,255,.05);border-radius:16px;padding:12px}
.phone-row .ic{width:44px;height:44px;border-radius:12px;flex-shrink:0}
.phone-row b{display:block;font-size:13px}
.phone-row small{font-size:11px;color:rgba(255,255,255,.55)}
.bar{height:8px;border-radius:4px;background:rgba(255,255,255,.08);margin-top:4px}
.float-card{position:absolute;background:#fff;color:var(--text);border-radius:14px;padding:12px 16px;box-shadow:var(--shadow);font-size:13px;font-weight:600;display:flex;align-items:center;gap:10px}
.float-card.a{left:-40px;top:90px}
.float-card.b{right:-30px;bottom:110px}
.float-card .dot{width:28px;height:28px;border-radius:8px;display:grid;place-items:center;color:#fff;font-size:14px}

/* ---------- Stats ---------- */
.stats{background:var(--bg-2);color:#fff;padding:44px 0}
.stats-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;text-align:center}
.stat b{display:block;font-size:34px;font-weight:800;letter-spacing:-.02em}
.stat span{color:rgba(255,255,255,.6);font-size:14px}

/* ---------- Apps ---------- */
.apps-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:56px}
.app-card{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:28px;transition:transform .25s,box-shadow .25s,border-color .25s;display:flex;flex-direction:column}
.app-card:hover{transform:translateY(-6px);box-shadow:var(--shadow);border-color:transparent}
.app-icon{width:72px;height:72px;border-radius:20px;display:grid;place-items:center;font-size:32px;color:#fff;margin-bottom:20px;box-shadow:0 10px 20px rgba(15,23,42,.15)}
.app-icon img{width:100%;height:100%;border-radius:20px;object-fit:cover}
.app-card h3{font-size:20px;font-weight:700;margin-bottom:4px}
.app-meta{font-size:13px;color:var(--muted);margin-bottom:12px}
.app-meta .star{color:#f59e0b}
.app-card p{color:var(--muted);font-size:15px;margin-bottom:24px;flex-grow:1}
.play-btn{display:inline-flex;align-items:center;gap:10px;background:#000;color:#fff;border-radius:10px;padding:8px 16px;align-self:flex-start;transition:opacity .2s}
.play-btn:hover{opacity:.85}
.play-btn svg{width:22px;height:22px}
.play-btn small{display:block;font-size:9px;letter-spacing:.06em;text-transform:uppercase;opacity:.8;line-height:1.1}
.play-btn strong{display:block;font-size:15px;line-height:1.1}
.g1{background:linear-gradient(135deg,#6366f1,#8b5cf6)}
.g2{background:linear-gradient(135deg,#06b6d4,#3b82f6)}
.g3{background:linear-gradient(135deg,#f97316,#ef4444)}
.g4{background:linear-gradient(135deg,#10b981,#06b6d4)}

/* ---------- Services ---------- */
.alt{background:var(--surface-2)}
.features{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-top:56px}
.feature{background:var(--surface);border-radius:var(--radius);padding:28px;border:1px solid var(--line)}
.feature .fi{width:48px;height:48px;border-radius:14px;display:grid;place-items:center;background:rgba(79,70,229,.1);color:var(--accent);margin-bottom:18px}
.feature .fi svg{width:24px;height:24px}
.feature h4{font-size:17px;font-weight:700;margin-bottom:8px}
.feature p{font-size:14.5px;color:var(--muted)}

/* ---------- About ---------- */
.about-grid{display:grid;grid-template-columns:1fr 1fr;gap:64px;align-items:center}
.about-visual{border-radius:24px;background:linear-gradient(135deg,var(--accent),var(--accent-2));aspect-ratio:4/3;position:relative;overflow:hidden;display:grid;place-items:center;color:#fff}
.about-visual .big{font-size:96px;font-weight:800;letter-spacing:-.04em;opacity:.95}
.about-visual:after{content:'';position:absolute;inset:0;background:radial-gradient(400px 200px at 80% 0%,rgba(255,255,255,.35),transparent 70%)}
.checklist{list-style:none;margin-top:28px;display:grid;gap:14px}
.checklist li{display:flex;gap:12px;align-items:flex-start;font-weight:500}
.checklist li:before{content:'\2713 ';flex-shrink:0;width:24px;height:24px;border-radius:50%;background:rgba(79,70,229,.12);color:var(--accent);display:grid;place-items:center;font-size:13px;font-weight:800}

/* ---------- Contact ---------- */
.contact-box{background:radial-gradient(700px 300px at 100% 0%,rgba(6,182,212,.3),transparent 60%),var(--bg);color:#fff;border-radius:28px;padding:64px;display:grid;grid-template-columns:1.2fr .8fr;gap:40px;align-items:center}
.contact-box .section-lead{color:rgba(255,255,255,.7)}
.contact-list{display:grid;gap:14px}
.contact-item{display:flex;gap:14px;align-items:center;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:14px;padding:16px 18px;transition:background .2s}
.contact-item:hover{background:rgba(255,255,255,.1)}
.contact-item small{display:block;color:rgba(255,255,255,.55);font-size:12px}
.contact-item b{font-size:15px;word-break:break-all}
.contact-item .ci{font-size:20px}

/* ---------- Footer ---------- */
.site-footer{background:var(--bg);color:rgba(255,255,255,.65);padding:56px 0 28px;font-size:14px}
.footer-top{display:flex;justify-content:space-between;gap:32px;flex-wrap:wrap;padding-bottom:32px;border-bottom:1px solid rgba(255,255,255,.08)}
.footer-links{display:flex;gap:28px;flex-wrap:wrap}
.footer-links a:hover{color:#fff}
.footer-bottom{padding-top:24px;display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}

/* ---------- Blogger pages (Privacy Policy, Terms, posts) ---------- */
.page-shell{padding:130px 0 80px;min-height:70vh;background:var(--surface-2)}
.post{max-width:820px;margin:0 auto 32px;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:48px}
.post-title{font-size:clamp(28px,4vw,38px);font-weight:800;letter-spacing:-.02em;line-height:1.2;margin-bottom:8px}
.post-date{color:var(--muted);font-size:14px;margin-bottom:28px}
.post-body{font-size:16.5px;color:#253047}
.post-body h2,.post-body h3{margin:28px 0 10px;color:var(--text)}
.post-body p,.post-body ul,.post-body ol{margin-bottom:16px}
.post-body ul,.post-body ol{padding-left:22px}
.post-body a{color:var(--accent);text-decoration:underline}
.post-body img{height:auto;border-radius:12px}
.post-list-item{display:block;max-width:820px;margin:0 auto 16px;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:24px 28px}
.post-list-item:hover{border-color:var(--accent)}
.post-list-item h2{font-size:20px}
.pager{max-width:820px;margin:0 auto;display:flex;justify-content:space-between}
.pager a{color:var(--accent);font-weight:600}

.is-home .page-shell{display:none}
.is-page .home-only{display:none}

/* Hide Blogger's default navbar */
#navbar,#navbar-iframe,.navbar{display:none!important;height:0!important;visibility:hidden!important}

/* ---------- Reveal animation ---------- */
.reveal{opacity:0;transform:translateY(24px);transition:opacity .7s ease,transform .7s ease}
.reveal.in{opacity:1;transform:none}

/* ---------- Responsive ---------- */
@media (max-width:980px){
  .hero-grid,.about-grid,.contact-box{grid-template-columns:1fr}
  .hero-visual{display:none}
  .apps-grid{grid-template-columns:repeat(2,1fr)}
  .features{grid-template-columns:repeat(2,1fr)}
  .stats-grid{grid-template-columns:repeat(2,1fr)}
}
@media (max-width:760px){
  .menu-btn{display:block}
  .nav-cta{display:none}
  .nav-links{position:absolute;top:72px;left:0;right:0;flex-direction:column;gap:0;background:rgba(11,16,32,.98);padding:8px 20px 20px;display:none}
  .nav-links.open{display:flex}
  .nav-links a{display:block;padding:14px 0;border-bottom:1px solid rgba(255,255,255,.06)}
  .site-header.menu-open{background:rgba(11,16,32,.98)}
  .section{padding:72px 0}
  .hero{padding:140px 0 88px}
  .apps-grid,.features{grid-template-columns:1fr}
  .contact-box{padding:36px 24px}
  .post{padding:28px 20px}
}

body.script:
//
(function(){
  var header=document.getElementById('header');
  var btn=document.getElementById('menuBtn');
  var links=document.getElementById('navLinks');
  function onScroll(){ if(window.scrollY>20){header.classList.add('scrolled');}else{header.classList.remove('scrolled');} }
  window.addEventListener('scroll',onScroll); onScroll();
  btn.addEventListener('click',function(){ links.classList.toggle('open'); header.classList.toggle('menu-open'); });
  links.addEventListener('click',function(e){ if(e.target.tagName==='A'){ links.classList.remove('open'); header.classList.remove('menu-open'); } });
  document.getElementById('year').textContent=new Date().getFullYear();
  var items=document.querySelectorAll('.reveal');
  if('IntersectionObserver' in window){
    var io=new IntersectionObserver(function(entries){
      entries.forEach(function(en){ if(en.isIntersecting){ en.target.classList.add('in'); io.unobserve(en.target); } });
    },{threshold:0.12});
    items.forEach(function(el){ io.observe(el); });
  } else { items.forEach(function(el){ el.classList.add('in'); }); }
})();
//
